SELECT *, SUM(revenue) OVER (PARTITION BY store_id ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_revenue, SUM(revenue) OVER (ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY revenue DESC, id) AS seq_no, LAST_VALUE(units) IGNORE NULLS OVER (PARTITION BY YEAR(sale_date), store_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_units, AVG(units) OVER (ORDER BY revenue, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS units_avg_2 FROM store_sales
